from collections import deque,Counter

def comps(grid,bg,diag=False):
    R,C=len(grid),len(grid[0]); vis=set(); out=[]
    steps=[(1,0),(-1,0),(0,1),(0,-1)]
    if diag: steps += [(1,1),(1,-1),(-1,1),(-1,-1)]
    for r in range(R):
      for c in range(C):
        if grid[r][c]==bg or (r,c) in vis: continue
        q=[(r,c)]; vis.add((r,c)); pts=[]
        while q:
          x,y=q.pop(); pts.append((x,y))
          for dx,dy in steps:
            p=(x+dx,y+dy)
            if 0<=p[0]<R and 0<=p[1]<C and grid[p[0]][p[1]]!=bg and p not in vis:
              vis.add(p);q.append(p)
        rs=[x for x,y in pts];cs=[y for x,y in pts]
        out.append(( (min(rs),max(rs),min(cs),max(cs)),len(pts),Counter(grid[x][y] for x,y in pts), sorted(pts)))
    return sorted(out,key=lambda x:(x[0][0],x[0][2]))
